def rope_kernel(q,k,theta,dists):
    d=np.arange(128); w=theta**(-2*d/256.)
    q1,q2=q[...,:128],q[...,128:]; k1,k2=k[...,:128],k[...,128:]
    re=q1*k1+q2*k2; im=q2*k1-q1*k2
    out=[]
    for D in dists:
        out.append((re*np.cos(w*D)-im*np.sin(w*D)).sum(-1))
    return np.mean(out,0)
